        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(Action<IHttpClientBuilder>? builder = null)
        {
            return AddApiHttpClients((Action<IServiceProvider, HttpClient>?)null, builder);
        }

        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(
            Action<HttpClient>? client,
            Action<IHttpClientBuilder>? builder = null)
        {
            var wrapped = client != null ? new Action<IServiceProvider, HttpClient>((_, httpClient) =>
            {
                client(httpClient);
            }) : null;
            return AddApiHttpClients(wrapped, builder);
        }

        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients(
            Action<IServiceProvider, HttpClient>? client,
            Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = (_, c) => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IAdAccountsApi, AdAccountsApi>("Org.OpenAPITools.Api.IAdAccountsApi", client));
            builders.Add(_services.AddHttpClient<IAdGroupsApi, AdGroupsApi>("Org.OpenAPITools.Api.IAdGroupsApi", client));
            builders.Add(_services.AddHttpClient<IAdsApi, AdsApi>("Org.OpenAPITools.Api.IAdsApi", client));
            builders.Add(_services.AddHttpClient<IAdvancedAuctionApi, AdvancedAuctionApi>("Org.OpenAPITools.Api.IAdvancedAuctionApi", client));
            builders.Add(_services.AddHttpClient<IAudienceInsightsApi, AudienceInsightsApi>("Org.OpenAPITools.Api.IAudienceInsightsApi", client));
            builders.Add(_services.AddHttpClient<IAudienceSharingApi, AudienceSharingApi>("Org.OpenAPITools.Api.IAudienceSharingApi", client));
            builders.Add(_services.AddHttpClient<IAudiencesApi, AudiencesApi>("Org.OpenAPITools.Api.IAudiencesApi", client));
            builders.Add(_services.AddHttpClient<IBillingApi, BillingApi>("Org.OpenAPITools.Api.IBillingApi", client));
            builders.Add(_services.AddHttpClient<IBoardsApi, BoardsApi>("Org.OpenAPITools.Api.IBoardsApi", client));
            builders.Add(_services.AddHttpClient<IBulkApi, BulkApi>("Org.OpenAPITools.Api.IBulkApi", client));
            builders.Add(_services.AddHttpClient<IBusinessAccessAssetsApi, BusinessAccessAssetsApi>("Org.OpenAPITools.Api.IBusinessAccessAssetsApi", client));
            builders.Add(_services.AddHttpClient<IBusinessAccessInviteApi, BusinessAccessInviteApi>("Org.OpenAPITools.Api.IBusinessAccessInviteApi", client));
